                Date range
              </Label>
              <div className="flex flex-wrap gap-1.5">
                {DATE_PRESETS.map(preset => (
                  <button
                    key={preset.label}
                    type="button"
                    onClick={() => applyPreset(preset)}
                    className="rounded-full px-3 py-1 text-xs bg-muted/50 text-muted-foreground hover:bg-muted transition-colors"
                  >
                    {preset.label}
                  </button>
                ))}
              </div>
              <div className="flex items-center gap-2">
                <Input
                  type="date"
                  value={local.dateFrom}
                  onChange={e => setLocal(prev => ({ ...prev, dateFrom: e.target.value }))}
                  className="text-sm h-8"
                />
                <span className="text-muted-foreground text-sm shrink-0">to</span>
                <Input
                  type="date"
                  value={local.dateTo}
                  onChange={e => setLocal(prev => ({ ...prev, dateTo: e.target.value }))}
                  className="text-sm h-8"
                />
              </div>
            </div>

            <Separator />

            {/* Amount range */}
            <div className="space-y-3">
              <Label className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                Amount
              </Label>
              <div className="flex items-center gap-2">
                <div className="relative flex-1">
                  <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                  <Input
                    placeholder="Min"
                    value={local.minAmount}
                    onChange={e => setLocal(prev => ({ ...prev, minAmount: e.target.value }))}
                    className="pl-6 text-sm h-8"
                    type="number"
                    min="0"
                  />
                </div>
                <span className="text-muted-foreground text-sm shrink-0">to</span>
                <div className="relative flex-1">
                  <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                  <Input
                    placeholder="Max"
