'use client'

import { useState, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'

interface ReceiptResendModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  paymentId: string | null
  defaultEmail: string
  defaultPhone: string
}

export function ReceiptResendModal({
  open,
  onOpenChange,
  paymentId,
  defaultEmail,
  defaultPhone,
}: ReceiptResendModalProps) {
  const [email, setEmail] = useState(defaultEmail)
  const [phone, setPhone] = useState(defaultPhone)
  const [isSending, setIsSending] = useState(false)

  useEffect(() => {
    if (open) {
      setEmail(defaultEmail)
      setPhone(defaultPhone)
    }
  }, [open, defaultEmail, defaultPhone])

  async function handleSend() {
    if (!paymentId) return
    setIsSending(true)
    try {
      const res = await fetch(`/api/payments/${paymentId}/resend-receipt`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email || undefined, phone: phone || undefined }),
      })
      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to send receipt')
      }
      toast.success(email ? `Receipt sent to ${email}` : 'Receipt sent')
      onOpenChange(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Send failed — try again')
    } finally {
      setIsSending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[380px]">
        <DialogHeader>
          <DialogTitle>Resend receipt</DialogTitle>
        </DialogHeader>
        <div className="space-y-3 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="receipt-email">Email</Label>
            <Input
              id="receipt-email"
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="client@example.com"
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="receipt-phone" className="text-muted-foreground">
              SMS (optional)
            </Label>
            <Input
              id="receipt-phone"
              type="tel"
              value={phone}
              onChange={e => setPhone(e.target.value)}
              placeholder="+1 (555) 000-0000"
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSending}>
            Cancel
          </Button>
          <Button
            onClick={handleSend}
            disabled={isSending || (!email && !phone)}
          >
            {isSending ? (
              <Loader2 className="animate-spin h-3.5 w-3.5 mr-1.5" />
            ) : null}
            Send
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

