// ─────────────────────────────────────────────────────────────────────────────
// Micro sparkline (Recharts-free, SVG path)
// ─────────────────────────────────────────────────────────────────────────────

function Sparkline({ data, width = 64, height = 28 }: { data: number[]; width?: number; height?: number }) {
  if (!data.length) return <div style={{ width, height }} />
  const max = Math.max(...data, 1)
  const pts = data.map((v, i) => {
    const x = (i / Math.max(data.length - 1, 1)) * width
    const y = height - (v / max) * height
    return `${x},${y}`
  })
  const d = `M ${pts.join(' L ')}`
  return (
    <svg width={width} height={height} aria-hidden="true">
      <path d={d} stroke="var(--color-primary)" strokeWidth="1.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

