function LeaderboardRow({
  rank,
  artist,
  isPrivate,
}: {
  rank: number
  artist: LeaderboardArtist
  isPrivate: boolean
}) {
  return (
    <div className="flex items-center gap-4 px-5 py-4 border-b border-border/40 last:border-0">
      {/* Rank */}
      <div className="w-7 shrink-0 flex items-center justify-center">
        {rank <= 3 ? (
          <MedalIcon rank={rank as 1 | 2 | 3} />
        ) : (
          <span className="text-sm font-mono text-muted-foreground tabular-nums">{rank}</span>
        )}
      </div>

      {/* Avatar + name */}
      <Avatar className="h-8 w-8 shrink-0">
        {artist.avatar_url ? (
          <AvatarImage src={artist.avatar_url} alt={artist.name} />
        ) : null}
        <AvatarFallback className="text-xs">
          {artist.name.slice(0, 2).toUpperCase()}
        </AvatarFallback>
      </Avatar>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{artist.name}</p>
        <p className="text-xs text-muted-foreground">
          {artist.appointment_count} session{artist.appointment_count !== 1 ? 's' : ''}
        </p>
      </div>

      {/* Sparkline */}
      {!isPrivate && artist.weekly_revenue.length > 0 && (
        <Sparkline data={artist.weekly_revenue} height={28} width={64} />
      )}

      {/* Total commission */}
      <div className="text-right shrink-0 min-w-[80px]">
        {isPrivate ? (
          <span className="text-sm text-muted-foreground">——</span>
        ) : (
          <span className="text-sm font-semibold font-mono tabular-nums">
            {formatCurrency(artist.commission_cents)}
          </span>
        )}
      </div>
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Main component
// ─────────────────────────────────────────────────────────────────────────────

const PERIOD_OPTIONS: LeaderPeriod[] = ['This month', 'This quarter', 'YTD']

export function LeaderboardTab({ from, to, period, isOwner }: LeaderboardTabProps) {
  const [activePeriod, setActivePeriod] = useState<LeaderPeriod>('This month')
  const [privateMode, setPrivateMode] = useState(true)

  const { data: artists = [], isLoading } = useQuery<LeaderboardArtist[]>({
    queryKey: ['commission-leaderboard', activePeriod],
    queryFn: async () => {
      const res = await fetch(
        `/api/commissions/leaderboard?period=${encodeURIComponent(activePeriod)}`,
      )
      if (!res.ok) throw new Error('Failed to load leaderboard')
      const body = await res.json() as { data: LeaderboardArtist[] }
      return body.data
    },
    staleTime: 60_000,
  })

  return (
    <div className="p-6 space-y-6">

      {/* Header row */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <Typography variant="h3">Top earners</Typography>

        <div className="flex items-center gap-3 flex-wrap">
          {/* Period pills */}
          <div className="flex items-center gap-1">
            {PERIOD_OPTIONS.map(p => (
              <button
                key={p}
                type="button"
                onClick={() => setActivePeriod(p)}
                className={cn(
                  'rounded-full px-3 py-1 text-xs transition-colors',
                  activePeriod === p
                    ? 'bg-secondary text-secondary-foreground border border-primary/30 font-medium'
                    : 'bg-muted/50 text-muted-foreground hover:bg-muted',
                )}
              >
                {p}
              </button>
            ))}
          </div>

          {/* Private mode toggle — owner only */}
          {isOwner && (
            <div className="flex items-center gap-1.5">
              <Switch
                id="private-mode"
                checked={privateMode}
                onCheckedChange={setPrivateMode}
                aria-label="Private mode"
              />
              <Label htmlFor="private-mode" className="text-xs text-muted-foreground cursor-pointer">
                Private
              </Label>
            </div>
          )}
        </div>
      </div>

      {/* Leaderboard */}
      {isLoading ? (
        <div className="rounded-xl border border-border overflow-hidden divide-y divide-border/40">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="px-5 py-4 flex items-center gap-4">
              <Skeleton className="h-5 w-5 rounded-full" />
              <Skeleton className="h-8 w-8 rounded-full" />
              <div className="flex-1 space-y-1.5">
                <Skeleton className="h-3.5 w-28" />
                <Skeleton className="h-3 w-16" />
              </div>
              <Skeleton className="h-4 w-16" />
            </div>
          ))}
        </div>
      ) : artists.length === 0 ? (
        <EmptyState
          icon={Trophy}
          title="No commissions this period"
          description="Commission data will appear once artists complete bookings."
        />
      ) : (
        <div className="rounded-xl border border-border overflow-hidden">
          {artists.slice(0, 10).map((artist, i) => (
            <LeaderboardRow
              key={artist.id}
              rank={i + 1}
              artist={artist}
              isPrivate={!isOwner && privateMode}
            />
          ))}
        </div>
      )}
    </div>
  )
}

