/**
 * GET /api/commissions/leaderboard — top 10 artists by commission earned.
 * Query param: period = 'This month' | 'This quarter' | 'YTD'
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import {
  startOfMonth,
  endOfMonth,
  startOfQuarter,
  endOfQuarter,
  startOfYear,
  endOfYear,
  format,
} from 'date-fns'

function getDateRange(period: string): { from: string; to: string } {
  const now = new Date()
  if (period === 'This quarter') {
    return {
      from: format(startOfQuarter(now), 'yyyy-MM-dd'),
      to: format(endOfQuarter(now), 'yyyy-MM-dd'),
    }
  }
  if (period === 'YTD') {
    return {
      from: format(startOfYear(now), 'yyyy-MM-dd'),
      to: format(endOfYear(now), 'yyyy-MM-dd'),
    }
  }
  // Default: This month
  return {
    from: format(startOfMonth(now), 'yyyy-MM-dd'),
    to: format(endOfMonth(now), 'yyyy-MM-dd'),
  }
}

export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  // Artists only see their own — owners/admins see all
  const isArtist = member.role === 'artist'
  if (isArtist) {
    return Response.json({ error: 'Forbidden — leaderboard is owner/admin only' }, { status: 403 })
  }

  const period = req.nextUrl.searchParams.get('period') ?? 'This month'
  const { from, to } = getDateRange(period)

  const { data: records, error } = await supabase
    .from('commission_records')
    .select('artist_id, total_cents')
    .eq('studio_id', member.studio_id)
    .gte('created_at', `${from}T00:00:00.000Z`)
    .lte('created_at', `${to}T23:59:59.999Z`)
    .in('status', ['approved', 'paid'])

  if (error) {
    logger.error({ error }, 'leaderboard query failed')
    return Response.json({ error: 'Failed to load leaderboard' }, { status: 500 })
  }

  // Aggregate by artist
  const byArtist = new Map<string, number>()
  for (const r of records ?? []) {
    byArtist.set(r.artist_id, (byArtist.get(r.artist_id) ?? 0) + (r.total_cents ?? 0))
  }

  // Fetch artist profiles
  const artistIds = [...byArtist.keys()]
  if (artistIds.length === 0) return Response.json({ data: [] })

  const { data: artists } = await supabase
    .from('artists')
    .select('id, full_name, avatar_url')
    .in('id', artistIds)

  const leaderboard = [...byArtist.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([id, total]) => {
      const artist = artists?.find(a => a.id === id)
      return {
        id,
        name: artist?.full_name ?? 'Unknown artist',
        avatar_url: artist?.avatar_url ?? null,
        appointment_count: (records ?? []).filter(r => r.artist_id === id).length,
        commission_cents: total,
        weekly_revenue: [] as number[],
      }
    })

  return Response.json({ data: leaderboard })
}

'use client'

import { Check, X, AlertTriangle } from 'lucide-react'
import { cn } from '@/lib/utils'

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

// Extended status to match Sprint 9 spec (5-state machine)
export type PayrollRunStatusExtended =
  | 'draft'
  | 'review'
  | 'approved'
  | 'processing'
  | 'paid'
  | 'closed'
  | 'cancelled'
  // Legacy Sprint 8 statuses mapped gracefully:
  | 'calculated'
  | 'failed'

type StepState = 'complete' | 'current' | 'upcoming' | 'error'

interface StepDef {
  id: string
  label: string
  description: string
}

interface PayrollStepperProps {
  runStatus: PayrollRunStatusExtended
  blockers?: string[]
}

// ─────────────────────────────────────────────────────────────────────────────
// Step definitions — ordered
// ─────────────────────────────────────────────────────────────────────────────

const STEPS: StepDef[] = [
  { id: 'draft',      label: 'Calculate',  description: 'Set pay period and review line items' },
  { id: 'review',     label: 'Review',     description: 'Verify amounts with your team' },
  { id: 'approved',   label: 'Approve',    description: 'Owner sign-off required' },
  { id: 'processing', label: 'Pay',        description: 'Initiating payouts' },
  { id: 'paid',       label: 'Complete',   description: 'All artists paid' },
]

// Map extended statuses to canonical step id order
const STATUS_TO_STEP_INDEX: Record<string, number> = {
  draft:      0,
  calculated: 1, // legacy — maps to review
  review:     1,
  approved:   2,
  processing: 3,
  paid:       4,
  closed:     4,
  cancelled:  -1,
  failed:     -1,
}

function getStepState(stepIndex: number, currentStatusIndex: number, runStatus: string): StepState {
  if (runStatus === 'cancelled' || runStatus === 'failed') {
    return stepIndex < currentStatusIndex ? 'complete' : 'upcoming'
  }
  if (stepIndex < currentStatusIndex) return 'complete'
  if (stepIndex === currentStatusIndex) return 'current'
  return 'upcoming'
}

// ─────────────────────────────────────────────────────────────────────────────
// Desktop stepper (horizontal)
// ─────────────────────────────────────────────────────────────────────────────

export function PayrollStepper({ runStatus, blockers = [] }: PayrollStepperProps) {
  const currentIdx = STATUS_TO_STEP_INDEX[runStatus] ?? 0

  return (
    <div className="w-full">
      {/* Horizontal stepper — desktop */}
      <div className="hidden md:block px-6 py-5 border-b border-border bg-card">
        <ol className="flex items-center w-full" role="list">
          {STEPS.map((step, i) => {
            const state = getStepState(i, currentIdx, runStatus)
            return (
              <li key={step.id} className={cn('flex items-center', i < STEPS.length - 1 && 'flex-1')}>
                <div className="flex flex-col items-center">
                  {/* Step indicator */}
                  <div
                    className={cn(
                      'flex h-8 w-8 items-center justify-center rounded-full transition-all duration-200',
                      state === 'complete' && 'bg-[var(--color-success)] text-white',
                      state === 'current' && 'bg-primary text-primary-foreground',
                      state === 'upcoming' && 'border-2 border-border bg-card text-muted-foreground',
                      state === 'error' && 'bg-destructive text-white',
                    )}
                    style={
                      state === 'current'
                        ? { boxShadow: '0 0 0 4px color-mix(in oklch, var(--color-primary) 20%, transparent)' }
                        : undefined
                    }
                    aria-current={state === 'current' ? 'step' : undefined}
                  >
                    {state === 'complete' ? (
                      <Check className="h-4 w-4" aria-hidden="true" />
                    ) : state === 'error' ? (
                      <X className="h-4 w-4" aria-hidden="true" />
                    ) : (
                      <span className="text-xs font-semibold tabular-nums" aria-hidden="true">
                        {i + 1}
                      </span>
                    )}
                  </div>

                  {/* Step label */}
                  <div className="mt-2 text-center">
                    <p
                      className={cn(
                        'text-xs font-medium',
                        state === 'current' ? 'text-foreground' : 'text-muted-foreground',
                      )}
                    >
                      {step.label}
                    </p>
                    {state === 'current' && (
                      <p className="text-[10px] text-muted-foreground mt-0.5 max-w-[90px] leading-snug">
                        {step.description}
                      </p>
                    )}
                  </div>
                </div>

                {/* Connector line */}
                {i < STEPS.length - 1 && (
                  <div
                    className={cn(
                      'flex-1 h-px mx-3 mt-[-28px]',
                      i < currentIdx ? 'bg-[var(--color-success)]' : 'bg-border',
                    )}
                    aria-hidden="true"
                  />
                )}
              </li>
            )
          })}
        </ol>

        {/* Blockers warning */}
        {blockers.length > 0 && (
          <div className="mt-4 flex items-center gap-2 rounded-lg bg-[var(--color-warning-bg)] border border-[var(--color-warning)]/20 px-4 py-2.5">
            <AlertTriangle className="h-4 w-4 text-[var(--color-warning)] shrink-0" aria-hidden="true" />
            <p className="text-sm text-[var(--color-warning-foreground)]">
              {blockers.join(' · ')}
            </p>
          </div>
        )}
      </div>

      {/* Vertical stepper — mobile */}
      <div className="md:hidden px-4 py-4 border-b border-border bg-card">
        <ol className="space-y-3" role="list">
          {STEPS.map((step, i) => {
            const state = getStepState(i, currentIdx, runStatus)
            return (
              <li key={step.id} className="flex items-start gap-3">
                <div
                  className={cn(
                    'flex h-6 w-6 shrink-0 items-center justify-center rounded-full mt-0.5',
                    state === 'complete' && 'bg-[var(--color-success)] text-white',
                    state === 'current' && 'bg-primary text-primary-foreground',
                    state === 'upcoming' && 'border-2 border-border bg-card text-muted-foreground',
                    state === 'error' && 'bg-destructive text-white',
                  )}
                >
                  {state === 'complete' ? (
                    <Check className="h-3 w-3" />
                  ) : state === 'error' ? (
                    <X className="h-3 w-3" />
                  ) : (
                    <span className="text-[10px] font-semibold">{i + 1}</span>
                  )}
                </div>
                <div>
                  <p
                    className={cn(
                      'text-sm font-medium leading-none',
                      state === 'current' ? 'text-foreground' : 'text-muted-foreground',
                    )}
                  >
                    {step.label}
                  </p>
                  {state === 'current' && (
                    <p className="text-xs text-muted-foreground mt-1 leading-snug">
                      {step.description}
                    </p>
                  )}
                </div>
              </li>
            )
          })}
        </ol>

        {blockers.length > 0 && (
          <div className="mt-3 flex items-center gap-2 rounded-lg bg-[var(--color-warning-bg)] px-3 py-2">
            <AlertTriangle className="h-3.5 w-3.5 text-[var(--color-warning)] shrink-0" />
            <p className="text-xs text-[var(--color-warning-foreground)]">
              {blockers.join(' · ')}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { ChevronDown, Pencil, MessageSquare, Send } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Skeleton } from '@/components/ui/skeleton'
import { Textarea } from '@/components/ui/textarea'
import { toast } from 'sonner'
import { cn, formatCurrency } from '@/lib/utils'
import { ArtistPayStatusBadge } from './ArtistPayStatusBadge'
import type { PayrollArtistStatus } from '@/lib/supabase/types'

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface LineItem {
  id: string
  label: string
  amount_cents: number
}

interface RunComment {
  id: string
  author_name: string
  author_id: string
  created_at: string
  body: string
}

export interface ArtistPayrollSummary {
  id: string
  artist_id: string
  artist_name: string
  artist_avatar: string | null
  session_count: number
  hours: number
  gross_cents: number
  net_cents: number
  deductions_cents: number
  pay_status: PayrollArtistStatus
  line_items: LineItem[]
  comments?: RunComment[]
}

interface ArtistPayrollRowProps {
  summary: ArtistPayrollSummary
  runStatus: string
  canEdit: boolean
  canManage: boolean
  currentUserId?: string
  currentUserName?: string
}

// ─────────────────────────────────────────────────────────────────────────────
// Comment thread
// ─────────────────────────────────────────────────────────────────────────────

function ArtistRunCommentThread({
  summaryId,
  canManage,
  comments = [],
  currentUserId = '',
  currentUserName = '',
}: {
  summaryId: string
  canManage: boolean
  comments?: RunComment[]
  currentUserId?: string
  currentUserName?: string
}) {
  const [body, setBody] = useState('')
  const [sending, setSending] = useState(false)
  const [localComments, setLocalComments] = useState<RunComment[]>(comments)

  async function handleSend() {
    if (!body.trim()) return
    setSending(true)
    try {
      const res = await fetch(`/api/payroll/artist-summaries/${summaryId}/comments`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ body: body.trim() }),
      })
      if (!res.ok) throw new Error('Failed to post comment')
      const data = await res.json() as { data: RunComment }
      setLocalComments(prev => [...prev, data.data])
      setBody('')
    } catch {
      toast.error('Failed to send comment')
    } finally {
      setSending(false)
    }
  }

  if (localComments.length === 0 && !canManage) return null

  return (
    <div className="space-y-2">
      {localComments.length > 0 && (
        <div className="space-y-2">
