'use client'

import { useState, useTransition } from 'react'
import { CheckCircle2, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import { logAuditAction } from '@/lib/audit'
import { format } from 'date-fns'

interface PayrollApprovalGateProps {
  runId: string
  totalNetCents: number
  payDate?: string | null
  onApproved: () => void
}

export function PayrollApprovalGate({
  runId,
  totalNetCents,
  payDate,
  onApproved,
}: PayrollApprovalGateProps) {
  const [confirmed, setConfirmed] = useState(false)
  const [confirmText, setConfirmText] = useState('')
  const [isPending, startTransition] = useTransition()

  const canApprove = confirmed && confirmText === 'APPROVE'

  function handleApprove() {
    if (!canApprove) return
    startTransition(async () => {
      try {
        const res = await fetch(`/api/payroll/runs/${runId}/approve`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
        })
        if (!res.ok) {
          const body = await res.json() as { error?: string }
          throw new Error(body.error ?? 'Approval failed')
        }
        const payDateFormatted = payDate
          ? format(new Date(payDate), 'EEEE, MMMM d')
          : 'the scheduled pay date'
        toast.success(`Payroll approved. Payouts scheduled for ${payDateFormatted}.`)
        onApproved()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Approval failed — try again')
      }
    })
  }

  return (
    <div className="mx-6 mt-4 rounded-xl border border-border bg-card p-5 space-y-4">
      <div className="flex items-center gap-2.5">
        <Checkbox
          id="confirm-amounts"
          checked={confirmed}
          onCheckedChange={checked => setConfirmed(checked === true)}
        />
        <label
          htmlFor="confirm-amounts"
          className="text-sm cursor-pointer leading-snug"
        >
          I have verified these amounts are correct
        </label>
      </div>

      <div>
        <label className="text-xs text-muted-foreground block mb-1.5">
          Type <span className="font-mono font-semibold text-foreground">APPROVE</span> to continue
        </label>
        <Input
          value={confirmText}
          onChange={e => setConfirmText(e.target.value)}
          placeholder="APPROVE"
          autoComplete="off"
          className="max-w-xs font-mono"
          aria-describedby="approve-hint"
        />
        <p id="approve-hint" className="sr-only">
          Type the word APPROVE to enable the approval button
        </p>
      </div>

      <Button
        onClick={handleApprove}
        disabled={!canApprove || isPending}
        className="w-full sm:w-auto"
      >
        {isPending ? (
          <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
        ) : (
          <CheckCircle2 className="h-4 w-4 mr-1.5" />
        )}
        Approve payroll run
      </Button>
    </div>
  )
}

