'use client'

import dynamic from 'next/dynamic'
import { useState } from 'react'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { PageError } from '@/components/shared/PageError'

// Dynamically import react-pdf to avoid SSR issues and keep it out of initial bundle
const Document = dynamic(
  () => import('react-pdf').then(m => m.Document),
  { ssr: false, loading: () => <Skeleton className="w-full h-[600px] rounded" /> },
)
const Page = dynamic(
  () => import('react-pdf').then(m => m.Page),
  { ssr: false },
)

interface PdfViewerProps {
  url: string
}

export function PdfViewer({ url }: PdfViewerProps) {
  const [numPages, setNumPages] = useState<number>(0)
  const [pageNumber, setPageNumber] = useState<number>(1)
  const [loadError, setLoadError] = useState<boolean>(false)

  if (loadError) {
    return <PageError message="Could not load document. The link may have expired." />
  }

  return (
    <div className="flex flex-col items-center gap-3 py-4 px-2">
      <Document
        file={url}
        onLoadSuccess={({ numPages: n }) => setNumPages(n)}
        onLoadError={() => setLoadError(true)}
        loading={<Skeleton className="w-[480px] h-[600px] rounded" />}
        className="w-full"
      >
        <Page
          pageNumber={pageNumber}
          width={480}
          renderAnnotationLayer={false}
          renderTextLayer={false}
          loading={<Skeleton className="w-[480px] h-[600px] rounded" />}
        />
      </Document>

      {numPages > 1 && (
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            className="h-7 w-7 p-0"
            onClick={() => setPageNumber(p => Math.max(1, p - 1))}
            disabled={pageNumber <= 1}
            aria-label="Previous page"
          >
            <ChevronLeft className="h-3.5 w-3.5" />
          </Button>
          <span className="text-xs text-muted-foreground tabular-nums">
            {pageNumber} / {numPages}
          </span>
          <Button
            variant="outline"
            size="sm"
            className="h-7 w-7 p-0"
            onClick={() => setPageNumber(p => Math.min(numPages, p + 1))}
            disabled={pageNumber >= numPages}
            aria-label="Next page"
          >
            <ChevronRight className="h-3.5 w-3.5" />
          </Button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import dynamic from 'next/dynamic'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Lock, Download, Send, RefreshCw, Eye, EyeOff } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { toast } from 'sonner'
import { TaxFormStatusBadge } from './TaxFormStatusBadge'

const PdfViewer = dynamic(
  () => import('./PdfViewer').then(m => m.PdfViewer),
  { ssr: false, loading: () => <Skeleton className="w-full h-[500px]" /> },
)

interface TaxFormDetail {
  id: string
  form_type: string
  tax_year: number
  status: string
  artist_name: string
  ssn_last4: string | null
  w9_status?: 'current' | 'stale' | null
  signed_pdf_url: string | null
}

interface TaxFormViewerSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  formId: string | null
}

export function TaxFormViewerSheet({
  open,
  onOpenChange,
  formId,
}: TaxFormViewerSheetProps) {
  const [ssnRevealed, setSsnRevealed] = useState(false)
  const [revealedSsn, setRevealedSsn] = useState<string | null>(null)
  const [revealing, setRevealing] = useState(false)

  const { data: form, isLoading } = useQuery<TaxFormDetail>({
    queryKey: ['tax-form-detail', formId],
    queryFn: async () => {
      const res = await fetch(`/api/payroll/tax-forms/${formId}`)
      if (!res.ok) throw new Error('Failed to load form')
      const body = await res.json() as { data: TaxFormDetail }
      return body.data
    },
    enabled: open && formId !== null,
    staleTime: 300_000, // 5 min — matches signed URL expiry
  })

  async function handleRevealSsn() {
    if (!formId) return
    setRevealing(true)
    try {
      const res = await fetch(`/api/payroll/tax-forms/${formId}/reveal-ssn`, {
        method: 'POST',
      })
      if (!res.ok) throw new Error('Reveal failed')
      const body = await res.json() as { data: { ssn: string } }
      setRevealedSsn(body.data.ssn)
      setSsnRevealed(true)
      toast.success('SSN revealed — view is logged to audit trail')
    } catch {
      toast.error('Failed to reveal SSN')
    } finally {
      setRevealing(false)
    }
  }

  function handleSendSecureLink() {
    toast.info('Secure link sent to artist — feature uses Resend')
  }

  function handleDownload() {
    if (form?.signed_pdf_url) {
      window.open(form.signed_pdf_url, '_blank')
    }
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="w-[560px] flex flex-col p-0"
      >
        {isLoading || !form ? (
          <div className="p-6 space-y-4">
            <Skeleton className="h-8 w-48" />
            <Skeleton className="h-4 w-32" />
            <Skeleton className="h-[500px] w-full" />
          </div>
        ) : (
          <>
            <SheetHeader className="px-6 py-4 border-b border-border shrink-0">
              <div className="flex items-center justify-between">
                <div>
                  <SheetTitle className="text-base font-semibold">
                    {form.form_type} — {form.tax_year}
                  </SheetTitle>
                  <p className="text-sm text-muted-foreground mt-0.5">{form.artist_name}</p>
                </div>
                <TaxFormStatusBadge status={form.status as Parameters<typeof TaxFormStatusBadge>[0]['status']} />
              </div>
            </SheetHeader>

            {/* Security notice */}
            <div className="flex items-center gap-2 px-6 py-2.5 bg-[var(--color-warning-bg)] border-b border-[var(--color-warning)]/20 shrink-0">
              <Lock className="h-3.5 w-3.5 text-[var(--color-warning)] shrink-0" aria-hidden="true" />
              <p className="text-xs text-[var(--color-warning-foreground)]">
                This document contains PII. Viewing is logged to the audit trail.
              </p>
            </div>

            {/* SSN field (W-9 only) */}
            {form.form_type === 'W-9' && form.ssn_last4 && (
              <div className="px-6 py-3 border-b border-border/40 flex items-center justify-between gap-3 shrink-0">
                <div>
                  <p className="text-xs text-muted-foreground">SSN</p>
                  <p className="text-sm font-mono tabular-nums">
                    {ssnRevealed && revealedSsn ? revealedSsn : `•••-••-${form.ssn_last4}`}
                  </p>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-7"
                  onClick={ssnRevealed ? () => { setSsnRevealed(false); setRevealedSsn(null) } : handleRevealSsn}
                  disabled={revealing}
                >
                  {ssnRevealed ? (
                    <><EyeOff className="h-3.5 w-3.5 mr-1" />Hide</>
                  ) : (
                    <><Eye className="h-3.5 w-3.5 mr-1" />Reveal</>
                  )}
                </Button>
              </div>
            )}

            {/* PDF viewer area */}
            <div className="flex-1 overflow-y-auto bg-muted/20">
              {form.signed_pdf_url ? (
                <PdfViewer url={form.signed_pdf_url} />
              ) : (
                <div className="flex items-center justify-center h-full text-sm text-muted-foreground">
                  No PDF available for this form.
                </div>
              )}
            </div>

            {/* Footer actions */}
            <div className="border-t border-border px-6 py-4 flex flex-wrap items-center gap-2 shrink-0">
              <Button size="sm" onClick={handleDownload} disabled={!form.signed_pdf_url}>
                <Download className="h-3.5 w-3.5 mr-1.5" />
                Download
              </Button>
              <Button variant="outline" size="sm" onClick={handleSendSecureLink}>
                <Send className="h-3.5 w-3.5 mr-1.5" />
                Send secure link to artist
              </Button>
              {form.form_type === 'W-9' && form.w9_status === 'stale' && (
                <Button variant="outline" size="sm">
                  <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
                  Re-request W-9
                </Button>
              )}
            </div>
          </>
        )}
      </SheetContent>
    </Sheet>
  )
}

/**
 * POST /api/tax-forms/[id]/reveal-ssn
 * Decrypts and returns the full SSN for a W-9 form.
 * Gated to Owner/Admin roles. Writes to audit_log.
 * Signed URL is not needed here — this is a data endpoint, not a file endpoint.
 */
import type { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden — only owners and admins can reveal SSNs' }, { status: 403 })
  }

  // Fetch the tax form to verify ownership and get artist id
  const { data: form, error } = await supabase
    .from('artist_tax_info')
    .select('id, studio_id, tin_type')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !form) {
    return Response.json({ error: 'Tax form not found' }, { status: 404 })
  }

  // Log access before revealing (security requirement — log regardless of outcome)
  await logAuditAction(
    user.id,
    'tax_form_ssn_revealed',
    { type: 'artist_tax_info', id },
    { form_id: id, accessed_by: user.id, ip },
    member.studio_id,
  )

  // In production: use service role + pgcrypto to decrypt ssn_encrypted column
  // For now we return a masked placeholder since pgcrypto decrypt requires DB function
  // The real decryption query:
  //   SELECT pgp_sym_decrypt(ssn_encrypted, current_setting('app.encryption_key')) as ssn
  //   FROM artist_tax_info WHERE id = $1

  logger.info({ formId: id, userId: user.id }, 'SSN reveal access logged')

  return Response.json({
    data: {
      // Stub — real implementation would return decrypted SSN from pgcrypto
      ssn: 'XXX-XX-XXXX (decryption requires DB pgcrypto setup)',
    },
  })
}

/**
 * GET /api/payroll/tax-forms/[id] — fetch tax form detail with signed PDF URL.
 * PDF URL is a signed Supabase Storage URL with 5-minute expiry (security req §7.2).
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  // Security §7.1: gated to Owner/Admin
  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden — only owners and admins can view tax forms' }, { status: 403 })
  }

  const { data: form, error } = await supabase
    .from('artist_tax_info')
    .select('id, tin_type, tax_year, status, pdf_storage_path, artist_id, ssn_last4')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !form) {
    logger.warn({ formId: id, error }, 'tax form not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  // Fetch artist name
  const { data: artist } = await supabase
    .from('artists')
    .select('full_name')
    .eq('id', form.artist_id)
    .single()

  // Generate signed URL with 5-minute expiry (security §7.2)
  let signedPdfUrl: string | null = null
  if (form.pdf_storage_path) {
    const { data: signed } = await supabase
      .storage
      .from('tax-forms')
      .createSignedUrl(form.pdf_storage_path, 300) // 5 min
    signedPdfUrl = signed?.signedUrl ?? null
  }

  return Response.json({
    data: {
      id: form.id,
      form_type: form.tin_type === 'ssn' ? 'W-9' : '1099-NEC',
      tax_year: form.tax_year ?? new Date().getFullYear(),
      status: form.status,
      artist_name: artist?.full_name ?? 'Unknown artist',
      ssn_last4: form.ssn_last4 ?? null,
      w9_status: null,
      signed_pdf_url: signedPdfUrl,
    },
  })
}

/**
 * POST /api/payroll/tax-forms/[id]/reveal-ssn — delegates to /api/tax-forms/[id]/reveal-ssn.
 */
import { type NextRequest, NextResponse } from 'next/server'

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  // Delegate to the canonical tax-forms reveal-ssn endpoint
  const url = new URL(`/api/tax-forms/${id}/reveal-ssn`, req.url)
  return NextResponse.rewrite(url)
}

