import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Loader2, Download } from 'lucide-react'
import { toast } from 'sonner'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'

type ExportPreset = 'accountant' | 'commission_detail' | '1099_export'

const PRESETS: { value: ExportPreset; label: string; description: string }[] = [
  {
    value: 'accountant',
    label: 'Payroll for accountant',
    description: 'Artist, period, gross, tax, net',
  },
  {
    value: 'commission_detail',
    label: 'Commission detail',
    description: 'Every commission line item',
  },
  {
    value: '1099_export',
    label: 'IRS 1099 export',
    description: 'Contractor earnings summary',
  },
]

const LARGE_EXPORT_THRESHOLD = 1000

interface CsvExportModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  studioId?: string
}

export function CsvExportModal({ open, onOpenChange, studioId }: CsvExportModalProps) {
  const [preset, setPreset] = useState<ExportPreset>('accountant')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')
  const [isExporting, setIsExporting] = useState(false)

  async function handleExport() {
    setIsExporting(true)
    try {
      const res = await fetch('/api/payroll/export/estimate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preset, from: dateFrom, to: dateTo }),
      })
      const estimate = res.ok
        ? (await res.json() as { count?: number }).count ?? 0
        : 0

      if (estimate > LARGE_EXPORT_THRESHOLD) {
        // Queue async export — user gets email when ready
        await enqueueJob('payroll-csv-export', {
          preset,
          from: dateFrom,
          to: dateTo,
          studioId,
        })
        toast.info('Export is being prepared. You\'ll receive an email with the download link.')
        onOpenChange(false)
        return
      }

      // Small export — direct download
      const params = new URLSearchParams()
      params.set('preset', preset)
      if (dateFrom) params.set('from', dateFrom)
      if (dateTo) params.set('to', dateTo)
      window.open(`/api/payroll/export?${params.toString()}`, '_blank')
      toast.success('Export started')
      onOpenChange(false)
    } catch (err) {
      logger.error({ err }, 'CSV export failed')
      toast.error('Export failed — try again')
    } finally {
      setIsExporting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[420px]">
        <DialogHeader>
          <DialogTitle>Export payroll data</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Date range */}
          <div className="space-y-1.5">
            <Label>Date range</Label>
            <div className="flex items-center gap-2">
              <Input
                type="date"
                value={dateFrom}
                onChange={e => setDateFrom(e.target.value)}
                className="text-sm h-8"
              />
              <span className="text-muted-foreground text-sm shrink-0">to</span>
              <Input
                type="date"
                value={dateTo}
                onChange={e => setDateTo(e.target.value)}
                className="text-sm h-8"
              />
            </div>
          </div>

          {/* Preset */}
          <div className="space-y-1.5">
            <Label>Preset</Label>
            <RadioGroup
              value={preset}
              onValueChange={v => { if (v) setPreset(v as ExportPreset) }}
              className="space-y-2"
            >
              {PRESETS.map(p => (
                <div key={p.value} className="flex items-start gap-3 rounded-lg border border-border p-3 cursor-pointer hover:bg-muted/30 transition-colors">
                  <RadioGroupItem value={p.value} id={`preset-${p.value}`} className="mt-0.5" />
                  <label htmlFor={`preset-${p.value}`} className="cursor-pointer flex-1">
                    <p className="text-sm font-medium">{p.label}</p>
                    <p className="text-xs text-muted-foreground">{p.description}</p>
                  </label>
                </div>
              ))}
            </RadioGroup>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isExporting}>
            Cancel
          </Button>
          <Button onClick={handleExport} disabled={isExporting}>
            {isExporting ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
            ) : (
              <Download className="h-3.5 w-3.5 mr-1.5" />
            )}
            Export CSV
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Loader2, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

type CancelStep = 'reason' | 'retention' | 'confirm'
type CancelReason =
  | 'too_expensive'
  | 'missing_features'
  | 'switching'
  | 'not_using'
  | 'other'

const CANCEL_REASONS: { value: CancelReason; label: string }[] = [
  { value: 'too_expensive',     label: 'Too expensive' },
  { value: 'missing_features',  label: 'Missing features I need' },
  { value: 'switching',         label: 'Switching to another tool' },
  { value: 'not_using',         label: 'Not using it enough' },
  { value: 'other',             label: 'Other' },
]

interface RetentionOffer {
  title: string
  description: string
  cta?: string
  ctaHref?: string
  onAccept?: () => void | Promise<void>
}

function getRetentionOffer(reason: CancelReason): RetentionOffer {
  switch (reason) {
    case 'too_expensive':
      return {
        title: 'Before you go — 30% off for 3 months',
        description: 'We\'d hate to lose you over price. Apply a 30% discount to your next 3 billing cycles.',
        cta: 'Apply discount',
      }
    case 'missing_features':
      return {
        title: 'Let\'s build what you need',
        description: 'Our team would love to understand what\'s missing. Book a 15-minute call and we\'ll prioritize your feedback.',
        cta: 'Book a call',
        ctaHref: 'https://cal.com/boldteq/feedback',
      }
    case 'switching':
      return {
        title: 'Export your data before you leave',
        description: 'We\'ll export all your client records, booking history, and consent forms as a ZIP file. You can also pause instead of cancel.',
        cta: 'Export my data',
      }
    case 'not_using':
      return {
        title: 'Pause for 90 days — no charge',
        description: 'Pause your subscription instead. Your data stays safe and you retain read-only access. No charge during the pause.',
        cta: 'Pause instead',
      }
    case 'other':
    default:
      return {
        title: 'Ready to cancel',
        description: 'We\'re sorry to see you go. Please continue to confirm your cancellation.',
      }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Progress dots
// ─────────────────────────────────────────────────────────────────────────────

function StepDots({ step }: { step: CancelStep }) {
  const steps: CancelStep[] = ['reason', 'retention', 'confirm']
  return (
    <div className="flex gap-1.5 items-center justify-center mb-1" role="presentation">
      {steps.map(s => (
        <div
          key={s}
          className={cn(
            'rounded-full transition-all duration-150',
            s === step ? 'h-1.5 w-4 bg-foreground' : 'h-1.5 w-1.5 bg-border',
          )}
        />
      ))}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Main modal
// ─────────────────────────────────────────────────────────────────────────────

interface CancelSubscriptionModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  currentPeriodEnd: string | null | undefined
  studioName?: string
  onConfirm: () => Promise<void>
}

export function CancelSubscriptionModal({
  open,
  onOpenChange,
  currentPeriodEnd,
  studioName = '',
  onConfirm,
}: CancelSubscriptionModalProps) {
  const [step, setStep] = useState<CancelStep>('reason')
  const [reason, setReason] = useState<CancelReason | ''>('')
  const [otherReason, setOtherReason] = useState('')
  const [confirmName, setConfirmName] = useState('')
  const [isCancelling, setIsCancelling] = useState(false)

  const periodEndDate = currentPeriodEnd
    ? new Date(currentPeriodEnd).toLocaleDateString('en-US', {
        month: 'long', day: 'numeric', year: 'numeric',
      })
    : 'the end of your billing period'

  function handleClose() {
    onOpenChange(false)
    // Reset after close animation
    setTimeout(() => {
      setStep('reason')
      setReason('')
      setOtherReason('')
      setConfirmName('')
    }, 300)
  }

  async function handleConfirmCancel() {
    if (confirmName !== studioName) return
    setIsCancelling(true)
    try {
      await onConfirm()
      toast.success('Subscription cancelled. Access continues until ' + periodEndDate)
      handleClose()
    } catch {
      toast.error('Failed to cancel — try again or contact support')
    } finally {
      setIsCancelling(false)
    }
  }

  const retentionOffer = reason ? getRetentionOffer(reason as CancelReason) : null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      {/* Step 1: Reason survey */}
      {step === 'reason' && (
        <DialogContent className="sm:max-w-[480px]">
          <StepDots step="reason" />
          <DialogHeader>
            <DialogTitle>We&apos;re sorry to see you go</DialogTitle>
            <DialogDescription>
              Help us improve — why are you cancelling?
            </DialogDescription>
          </DialogHeader>

          <RadioGroup
            value={reason}
            onValueChange={v => { if (v) setReason(v as CancelReason) }}
            className="space-y-2 py-2"
          >
            {CANCEL_REASONS.map(r => (
              <div
                key={r.value}
                className="flex items-center gap-3 rounded-lg border border-border px-4 py-3 cursor-pointer hover:bg-muted/30 transition-colors"
              >
                <RadioGroupItem value={r.value} id={`reason-${r.value}`} />
                <Label htmlFor={`reason-${r.value}`} className="cursor-pointer text-sm font-normal">
                  {r.label}
                </Label>
              </div>
            ))}
          </RadioGroup>

          {reason === 'other' && (
            <Textarea
              placeholder="Tell us more..."
              value={otherReason}
              onChange={e => setOtherReason(e.target.value)}
              rows={2}
              className="mt-2 text-sm"
            />
          )}

          <DialogFooter className="mt-2">
            <Button variant="ghost" onClick={handleClose}>Keep my subscription</Button>
            <Button
              variant="outline"
              disabled={!reason}
              onClick={() => setStep(reason === 'other' ? 'confirm' : 'retention')}
            >
              Continue
            </Button>
          </DialogFooter>
        </DialogContent>
      )}

      {/* Step 2: Retention offer */}
      {step === 'retention' && retentionOffer && (
        <DialogContent className="sm:max-w-[480px]">
          <StepDots step="retention" />
          <DialogHeader>
            <DialogTitle>{retentionOffer.title}</DialogTitle>
            <DialogDescription>{retentionOffer.description}</DialogDescription>
          </DialogHeader>

          <div className="py-3 space-y-3">
            {retentionOffer.cta && (
              retentionOffer.ctaHref ? (
                <Button
                  className="w-full"
                  asChild
                  onClick={handleClose}
                >
                  <a href={retentionOffer.ctaHref} target="_blank" rel="noopener noreferrer">
                    {retentionOffer.cta}
                    <ExternalLink className="h-3.5 w-3.5 ml-1.5" />
                  </a>
                </Button>
              ) : (
                <Button
                  className="w-full"
                  onClick={() => {
                    toast.info('Feature coming soon — contact support to apply.')
                    handleClose()
                  }}
                >
                  {retentionOffer.cta}
                </Button>
              )
            )}
          </div>

          <DialogFooter>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setStep('confirm')}
              className="text-muted-foreground text-xs"
            >
              No thanks, continue cancelling
            </Button>
          </DialogFooter>
        </DialogContent>
      )}

      {/* Step 3: Final confirmation */}
      {step === 'confirm' && (
        <DialogContent className="sm:max-w-[440px]">
          <StepDots step="confirm" />
          <DialogHeader>
            <DialogTitle>Confirm cancellation</DialogTitle>
            <DialogDescription>
              Your subscription will remain active until{' '}
              <strong>{periodEndDate}</strong>. After that, your studio will
              switch to read-only.
            </DialogDescription>
          </DialogHeader>

          <div className="rounded-xl bg-[var(--color-warning-bg)] border border-[var(--color-warning)]/20 px-4 py-3 my-3 space-y-1">
            <p className="text-sm font-medium text-[var(--color-warning-foreground)]">
              What happens when you cancel:
            </p>
            <ul className="text-xs text-[var(--color-warning-foreground)] space-y-1 list-disc list-inside">
              <li>Access ends on {periodEndDate}</li>
              <li>Your data is retained for 90 days</li>
              <li>New bookings cannot be accepted</li>
            </ul>
          </div>

          {studioName && (
            <div className="space-y-1.5">
              <Label>
                Type your studio name to confirm:{' '}
                <span className="font-mono text-foreground">
                  &quot;{studioName}&quot;
                </span>
              </Label>
              <Input
                value={confirmName}
                onChange={e => setConfirmName(e.target.value)}
                placeholder={studioName}
                autoComplete="off"
              />
            </div>
          )}

          <DialogFooter className="mt-2">
            <Button variant="ghost" onClick={handleClose}>Keep my subscription</Button>
            <Button
              variant="destructive"
              disabled={(studioName.length > 0 && confirmName !== studioName) || isCancelling}
              onClick={handleConfirmCancel}
            >
              {isCancelling && <Loader2 className="h-4 w-4 animate-spin mr-1.5" />}
              Cancel subscription
            </Button>
          </DialogFooter>
        </DialogContent>
      )}
    </Dialog>
  )
}

