'use client'

import { useState, useRef, useCallback } from 'react'
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  ReferenceArea,
} from 'recharts'
import { useQuery } from '@tanstack/react-query'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { cn, formatCurrency } from '@/lib/utils'
import { format, parseISO } from 'date-fns'

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface MrrDataPoint {
  date: string
  mrr_cents: number
}

interface MrrOverview {
  mrr_cents: number
  mrr_delta_pct: number
  series: MrrDataPoint[]
}

type TimeRange = '7D' | '30D' | '90D' | 'YTD' | 'All'

// ─────────────────────────────────────────────────────────────────────────────
// Delta badge
// ─────────────────────────────────────────────────────────────────────────────

function DeltaBadge({ delta }: { delta: number }) {
  const positive = delta >= 0
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 text-xs font-semibold rounded-full px-2 py-0.5 mt-1',
        positive
          ? 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]'
          : 'bg-destructive/10 text-destructive',
      )}
    >
      {positive ? '↑' : '↓'} {Math.abs(delta).toFixed(1)}% MoM
    </span>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Custom tooltip
// ─────────────────────────────────────────────────────────────────────────────

interface TooltipPayloadEntry {
  value: number
}

function MrrTooltip({
  active,
  payload,
  label,
  onDayClick,
}: {
  active?: boolean
  payload?: TooltipPayloadEntry[]
  label?: string
  onDayClick?: (date: string) => void
}) {
  if (!active || !payload?.length || !label) return null
  const mrrCents = payload[0]?.value ?? 0
  return (
    <div className="rounded-lg border border-border bg-card shadow-[var(--shadow-lift)] px-3 py-2.5 min-w-[160px]">
      <p className="text-xs text-muted-foreground mb-1">
        {format(parseISO(label), 'MMM d, yyyy')}
      </p>
      <p className="text-sm font-semibold font-mono tabular-nums">
        {formatCurrency(mrrCents)}
      </p>
      {onDayClick && (
        <button
          type="button"
          className="text-xs text-primary mt-1 hover:underline block"
          onClick={() => onDayClick(label)}
        >
          View events →
        </button>
      )}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// MrrDashboard
// ─────────────────────────────────────────────────────────────────────────────

interface MrrDashboardProps {
  onDayClick?: (date: string) => void
}

const TIME_RANGES: TimeRange[] = ['7D', '30D', '90D', 'YTD', 'All']

export function MrrDashboard({ onDayClick }: MrrDashboardProps) {
  const [activeRange, setActiveRange] = useState<TimeRange>('90D')
  const [dragStart, setDragStart] = useState<string | null>(null)
  const [dragEnd, setDragEnd] = useState<string | null>(null)
  const [isZoomed, setIsZoomed] = useState(false)
  const [zoomedData, setZoomedData] = useState<MrrDataPoint[] | null>(null)
  const isDragging = useRef(false)

  const { data, isLoading } = useQuery<MrrOverview>({
    queryKey: ['admin-mrr', activeRange],
    queryFn: async () => {
      const res = await fetch(`/api/admin/billing/mrr?range=${activeRange}`)
      if (!res.ok) throw new Error('Failed to load MRR data')
      return res.json() as Promise<MrrOverview>
    },
    staleTime: 60_000,
  })

  const chartData = zoomedData ?? data?.series ?? []

  function formatAxisDate(dateStr: string) {
    try {
      return format(parseISO(dateStr), 'MMM d')
    } catch {
      return dateStr
    }
  }

  const handleMouseDown = useCallback((e: { activeLabel?: string }) => {
    if (!e.activeLabel) return
    isDragging.current = true
    setDragStart(e.activeLabel)
    setDragEnd(null)
  }, [])

  const handleMouseMove = useCallback((e: { activeLabel?: string }) => {
    if (!isDragging.current || !e.activeLabel) return
    setDragEnd(e.activeLabel)
  }, [])

  const handleMouseUp = useCallback(() => {
    if (!isDragging.current) return
    isDragging.current = false
    if (dragStart && dragEnd && dragStart !== dragEnd && data?.series) {
      const series = data.series
      const startIdx = series.findIndex(d => d.date >= dragStart)
      const endIdx = series.findLastIndex(d => d.date <= dragEnd)
      if (startIdx >= 0 && endIdx > startIdx) {
        setZoomedData(series.slice(startIdx, endIdx + 1))
        setIsZoomed(true)
      }
    }
    setDragStart(null)
    setDragEnd(null)
  }, [dragStart, dragEnd, data?.series])

  function resetZoom() {
    setZoomedData(null)
    setIsZoomed(false)
    setDragStart(null)
    setDragEnd(null)
  }

  if (isLoading) {
    return (
      <Card className="rounded-xl border border-border shadow-[var(--shadow-card)]">
        <CardHeader className="pb-0 px-6 pt-5">
          <Skeleton className="h-8 w-32" />
          <Skeleton className="h-4 w-20 mt-2" />
        </CardHeader>
        <CardContent className="px-2 pt-4 pb-2">
          <Skeleton className="h-[220px] w-full" />
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="rounded-xl border border-border shadow-[var(--shadow-card)] relative">
      <CardHeader className="pb-0 px-6 pt-5">
        <div className="flex items-start justify-between">

          {/* Left: value + delta */}
          <div>
            <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground mb-1">
              MRR
            </p>
            <p className="text-3xl font-bold tabular-nums tracking-tight">
              {formatCurrency(data?.mrr_cents ?? 0)}
            </p>
            <DeltaBadge delta={data?.mrr_delta_pct ?? 0} />
          </div>

          {/* Right: time range pills */}
          <div className="flex items-center gap-1 flex-wrap">
            {TIME_RANGES.map(range => (
              <button
                key={range}
                type="button"
                onClick={() => { setActiveRange(range); resetZoom() }}
                className={cn(
                  'px-2.5 py-1 rounded-full text-xs font-medium transition-colors duration-100',
                  activeRange === range
                    ? 'bg-primary/10 text-primary ring-1 ring-primary/30'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted',
                )}
              >
                {range}
              </button>
            ))}
          </div>
        </div>
      </CardHeader>

      <CardContent className="px-2 pt-4 pb-2 select-none">
        <ResponsiveContainer width="100%" height={220}>
          <AreaChart
            data={chartData}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onDoubleClick={resetZoom}
          >
            <defs>
              <linearGradient id="mrrGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="var(--color-electric-purple)" stopOpacity={0.15} />
                <stop offset="95%" stopColor="var(--color-electric-purple)" stopOpacity={0} />
              </linearGradient>
            </defs>

            <CartesianGrid
              stroke="var(--color-border)"
              vertical={false}
              strokeDasharray="3 3"
            />
            <XAxis
              dataKey="date"
              tick={{ fill: 'var(--color-muted-foreground)', fontSize: 11 }}
              tickLine={false}
              axisLine={false}
              tickFormatter={formatAxisDate}
            />
            <YAxis
              tick={{ fill: 'var(--color-muted-foreground)', fontSize: 11 }}
              tickLine={false}
              axisLine={false}
              tickFormatter={v => `$${((v as number) / 100).toLocaleString()}`}
              width={60}
            />
            <Tooltip
              content={
                <MrrTooltip onDayClick={onDayClick} />
              }
            />
            <Area
              type="monotone"
              dataKey="mrr_cents"
              stroke="var(--color-electric-purple)"
              strokeWidth={2}
              fill="url(#mrrGradient)"
              dot={false}
              activeDot={{
                r: 4,
                fill: 'var(--color-electric-purple)',
                strokeWidth: 0,
              }}
            />

            {/* Drag-zoom selection */}
            {dragStart && dragEnd && (
              <ReferenceArea
                x1={dragStart}
                x2={dragEnd}
                fill="var(--color-primary)"
                fillOpacity={0.08}
              />
            )}
          </AreaChart>
        </ResponsiveContainer>
      </CardContent>

      {/* Reset zoom button */}
      {isZoomed && (
        <button
          type="button"
          onClick={resetZoom}
          className="absolute top-4 right-[180px] text-xs text-primary hover:underline"
        >
          Reset zoom
        </button>
      )}
    </Card>
  )
}

'use client'

import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState } from '@/components/shared/EmptyState'
import { Grid3X3 } from 'lucide-react'
import { format, parseISO } from 'date-fns'

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface CohortRow {
  cohort_month: string   // ISO date string: "2026-01-01"
  retentions: (number | null)[]  // index 0 = month 0 (always 100), index N = % at month N
}

// ─────────────────────────────────────────────────────────────────────────────
// Color mapping (2 raw oklch values permitted by Vega for intermediate shading)
// ─────────────────────────────────────────────────────────────────────────────

function cohortCellBg(pct: number | null): string {
  if (pct === null) return 'transparent'
  if (pct >= 80) return 'var(--color-success-bg)'
  if (pct >= 60) return 'oklch(94% 0.04 145)' // Vega-approved intermediate green
  if (pct >= 40) return 'var(--color-warning-bg)'
  return 'oklch(94% 0.04 27)'                  // Vega-approved intermediate red
}

function cohortCellText(pct: number | null): string {
  if (pct === null) return 'var(--color-muted-foreground)'
  if (pct >= 80) return 'var(--color-success-foreground)'
  if (pct >= 60) return 'oklch(32% 0.12 145)'
  if (pct >= 40) return 'var(--color-warning-foreground)'
  return 'oklch(35% 0.18 27)'
}

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

interface ChurnCohortGridProps {
  data: CohortRow[]
  isLoading?: boolean
}

export function ChurnCohortGrid({ data, isLoading }: ChurnCohortGridProps) {
  if (isLoading) {
    return <Skeleton className="h-64 w-full rounded-xl" />
  }

  if (!data.length) {
    return (
      <EmptyState
        icon={Grid3X3}
        title="No cohort data yet"
        description="Cohorts appear after at least 2 months of subscriber data."
      />
    )
  }

  const maxMonths = Math.max(...data.map(r => r.retentions.length))

  return (
    <div className="overflow-x-auto rounded-xl border border-border">
      <table className="w-full text-xs border-separate border-spacing-0.5">
        <thead>
          <tr>
            <th className="text-left px-3 py-2 text-muted-foreground font-medium sticky left-0 bg-card z-10 whitespace-nowrap">
              Cohort
            </th>
            {Array.from({ length: maxMonths }, (_, i) => (
              <th key={i} className="px-2 py-1.5 text-muted-foreground font-medium tabular-nums text-center min-w-[40px]">
                M+{i}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map(row => (
            <tr key={row.cohort_month}>
              <td className="px-3 py-1.5 font-medium text-foreground sticky left-0 bg-card z-10 whitespace-nowrap">
                {format(parseISO(row.cohort_month), 'MMM yyyy')}
              </td>
              {row.retentions.map((pct, i) => (
                <td
                  key={i}
                  className="px-2 py-1.5 text-center rounded tabular-nums font-medium"
                  style={{
                    background: cohortCellBg(pct),
                    color: cohortCellText(pct),
                  }}
                  title={pct !== null ? `${pct.toFixed(1)}% retention` : 'No data'}
                >
                  {pct === null ? '—' : `${Math.round(pct)}%`}
                </td>
              ))}
              {/* Pad shorter rows */}
              {row.retentions.length < maxMonths &&
                Array.from({ length: maxMonths - row.retentions.length }, (_, i) => (
                  <td key={`pad-${i}`} className="px-2 py-1.5 text-center text-muted-foreground/40">
                    —
                  </td>
                ))
              }
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

