// ─────────────────────────────────────────────────────────────────────────────
// KPI card with sparkline delta
// ─────────────────────────────────────────────────────────────────────────────

interface KpiCardProps {
  label: string
  value: string
  delta?: string
  trend?: 'up' | 'down' | 'neutral'
}

function KpiCard({ label, value, delta, trend = 'neutral' }: KpiCardProps) {
  return (
    <div className="rounded-xl border border-border bg-card p-4 shadow-[var(--shadow-soft)]">
      <p className="text-[11px] font-medium uppercase tracking-[0.04em] text-muted-foreground mb-2">
        {label}
      </p>
      <p className="text-2xl font-bold tabular-nums tracking-tight text-foreground">
        {value}
      </p>
      {delta && (
        <p
          className={
            trend === 'up'
              ? 'mt-1 text-xs font-medium text-[var(--color-success)] flex items-center gap-0.5'
              : trend === 'down'
              ? 'mt-1 text-xs font-medium text-destructive flex items-center gap-0.5'
              : 'mt-1 text-xs text-muted-foreground'
          }
        >
          {trend === 'up' && <TrendingUp className="size-3" aria-hidden="true" />}
          {trend === 'down' && <TrendingDown className="size-3" aria-hidden="true" />}
          {delta}
        </p>
