}

// ─────────────────────────────────────────────────────────────────────────────
// Day events drawer
// ─────────────────────────────────────────────────────────────────────────────

const EVENT_LABELS: Record<string, string> = {
  new_subscription:   'New subscription',
  cancellation:       'Cancellation',
  upgrade:            'Upgrade',
  downgrade:          'Downgrade',
  payment_failed:     'Payment failed',
  payment_succeeded:  'Payment succeeded',
  refund:             'Refund',
  trial_started:      'Trial started',
  trial_ended:        'Trial ended',
}

function DayEventsDrawer({
  date,
  open,
  onOpenChange,
}: {
  date: string | null
  open: boolean
  onOpenChange: (v: boolean) => void
}) {
  const [data, setData] = useState<DayEventsResponse | null>(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!open || !date) { setData(null); return }
    setLoading(true)
    fetch(`/api/admin/billing/day-events?date=${date}`)
      .then(r => r.json())
      .then((d: DayEventsResponse) => { setData(d); setLoading(false) })
      .catch(() => setLoading(false))
  }, [open, date])

  const displayDate = date
    ? (() => {
        try { return format(parseISO(date), 'MMMM d, yyyy') }
        catch { return date }
      })()
    : ''

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-[420px] flex flex-col">
        <SheetHeader>
          <SheetTitle>Events — {displayDate}</SheetTitle>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto py-4 space-y-2">
          {loading && (
            <div className="space-y-2">
              {Array.from({ length: 5 }).map((_, i) => (
                <Skeleton key={i} className="h-14 rounded-lg" />
              ))}
            </div>
          )}

          {!loading && (!data?.events.length) && (
            <div className="flex flex-col items-center justify-center h-40 text-center">
              <p className="text-sm text-muted-foreground">No billing events on this day.</p>
            </div>
          )}

          {!loading && data?.events.map(ev => (
            <div
              key={ev.id}
              className="rounded-lg border border-border bg-card px-4 py-3 flex items-start gap-3"
            >
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">{ev.studio_name}</p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {EVENT_LABELS[ev.type] ?? ev.type}
                </p>
              </div>
              {ev.amount_cents > 0 && (
                <p className="text-sm font-semibold tabular-nums text-foreground shrink-0">
                  {formatCurrency(ev.amount_cents)}
                </p>
              )}
            </div>
          ))}
        </div>
      </SheetContent>
    </Sheet>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Main component
// ─────────────────────────────────────────────────────────────────────────────

export function AdminBillingClient() {
  const [overview, setOverview] = useState<OverviewData | null>(null)
  const [subs, setSubs] = useState<SubsResponse>({ subscriptions: [], total: 0 })
  const [webhooks, setWebhooks] = useState<WebhooksResponse>({ events: [], total: 0 })
  const [failedPayments, setFailedPayments] = useState<FailedPaymentsResponse>({ payments: [], total: 0 })
  const [churnData, setChurnData] = useState<ChurnData | null>(null)
  const [ltvData, setLtvData] = useState<LtvData | null>(null)

  const [subsPage, setSubsPage] = useState(1)
  const [webhooksPage, setWebhooksPage] = useState(1)
  const [failedPage, setFailedPage] = useState(1)

  const [loadingOverview, setLoadingOverview] = useState(true)
  const [loadingSubs, setLoadingSubs] = useState(true)
  const [loadingWebhooks, setLoadingWebhooks] = useState(false)
  const [loadingFailed, setLoadingFailed] = useState(false)
  const [loadingChurn, setLoadingChurn] = useState(false)
  const [loadingLtv, setLoadingLtv] = useState(false)

  const [activeTab, setActiveTab] = useState('subscriptions')
  const [dayEventsDate, setDayEventsDate] = useState<string | null>(null)
  const [dayEventsOpen, setDayEventsOpen] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetch('/api/admin/billing/overview', { signal: controller.signal })
      .then(r => r.json())
      .then((d: OverviewData) => { setOverview(d); setLoadingOverview(false) })
      .catch(() => { setLoadingOverview(false) })
    return () => controller.abort()
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    fetch(`/api/admin/billing/subscriptions?page=${subsPage}&limit=${LIMIT}`, { signal: controller.signal })
      .then(r => r.json())
      .then((d: SubsResponse) => { setSubs(d); setLoadingSubs(false) })
      .catch(() => { setLoadingSubs(false) })
    return () => controller.abort()
  }, [subsPage])

  const loadWebhooks = useCallback((page: number) => {
    setLoadingWebhooks(true)
    fetch(`/api/admin/billing/webhooks?page=${page}&limit=${LIMIT}`)
      .then(r => r.json())
      .then((d: WebhooksResponse) => setWebhooks(d))
      .catch(() => undefined)
      .finally(() => setLoadingWebhooks(false))
  }, [])

  const loadFailedPayments = useCallback((page: number) => {
    setLoadingFailed(true)
    fetch(`/api/admin/billing/failed-payments?page=${page}&limit=${LIMIT}`)
      .then(r => r.json())
      .then((d: FailedPaymentsResponse) => setFailedPayments(d))
      .catch(() => undefined)
      .finally(() => setLoadingFailed(false))
  }, [])

  const loadChurn = useCallback(() => {
    if (churnData) return
    setLoadingChurn(true)
    fetch('/api/admin/billing/churn-cohorts')
      .then(r => r.json())
      .then((d: ChurnData) => setChurnData(d))
      .catch(() => undefined)
      .finally(() => setLoadingChurn(false))
  }, [churnData])

  const loadLtv = useCallback(() => {
    if (ltvData) return
    setLoadingLtv(true)
    fetch('/api/admin/billing/ltv')
      .then(r => r.json())
      .then((d: LtvData) => setLtvData(d))
      .catch(() => undefined)
      .finally(() => setLoadingLtv(false))
  }, [ltvData])

  function handleDayClick(date: string) {
    setDayEventsDate(date)
    setDayEventsOpen(true)
  }

  function handleTabChange(tab: string) {
    setActiveTab(tab)
    if (tab === 'webhooks') loadWebhooks(webhooksPage)
    if (tab === 'failed') loadFailedPayments(failedPage)
    if (tab === 'churn') loadChurn()
    if (tab === 'ltv') loadLtv()
  }

  return (
    <div className="p-6 max-w-7xl space-y-6">

      {/* Page header */}
      <div>
        <Typography variant="h1">Billing</Typography>
        <p className="mt-1 text-sm text-muted-foreground">
          Platform billing overview and subscription management.
        </p>
      </div>

      {/* Failed payments banner */}
      {!loadingOverview && (overview?.pastDueCount ?? 0) > 0 && (
        <FailedPaymentsBanner
          count={overview!.pastDueCount}
          onView={() => handleTabChange('failed')}
        />
      )}

      {/* MRR chart */}
      <MrrDashboard onDayClick={handleDayClick} />

      {/* KPI row */}
      {loadingOverview ? (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-xl" />)}
        </div>
      ) : overview ? (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <KpiCard
            label="New MRR"
            value={formatCurrency(overview.newMrrCents)}
            delta="New subscribers"
            trend="up"
          />
          <KpiCard
            label="Expansion"
            value={formatCurrency(overview.expansionMrrCents)}
            delta="Upgrades this month"
            trend="up"
          />
          <KpiCard
            label="Contraction"
            value={formatCurrency(overview.contractionMrrCents)}
            delta="Downgrades this month"
            trend={overview.contractionMrrCents > 0 ? 'down' : 'neutral'}
          />
          <KpiCard
            label="Churned MRR"
            value={formatCurrency(overview.churnedMrrCents)}
            delta={`${overview.cancelledLast30dCount} cancelled this month`}
            trend={overview.churnedMrrCents > 0 ? 'down' : 'neutral'}
          />
        </div>
      ) : null}

