import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { subDays, startOfYear, format, eachDayOfInterval } from 'date-fns'

export const dynamic = 'force-dynamic'

type TimeRange = '7D' | '30D' | '90D' | 'YTD' | 'All'

function getRangeStart(range: TimeRange): Date {
  const now = new Date()
  switch (range) {
    case '7D':  return subDays(now, 7)
    case '30D': return subDays(now, 30)
    case '90D': return subDays(now, 90)
    case 'YTD': return startOfYear(now)
    case 'All': return new Date('2024-01-01')
  }
}

/**
 * GET /api/admin/billing/mrr?range=90D
 * Returns current MRR, MoM delta %, and daily series for the selected range.
 * Platform admin only.
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const rawRange = req.nextUrl.searchParams.get('range') ?? '90D'
  const VALID_RANGES: TimeRange[] = ['7D', '30D', '90D', 'YTD', 'All']
  const range: TimeRange = VALID_RANGES.includes(rawRange as TimeRange)
    ? (rawRange as TimeRange)
    : '90D'

  const supabase = createServiceRoleClient()
  const rangeStart = getRangeStart(range)

  // Fetch all active/trialing subscriptions to compute daily MRR series
  // In production this would use a pre-aggregated mrr_snapshots table.
  // Here we approximate by fetching subscriptions and sampling daily.
  const { data: subs, error } = await supabase
    .from('subscriptions')
    .select('price_cents, billing_cycle, status, created_at, current_period_end, cancelled_at')
    .in('status', ['active', 'trialing', 'canceled', 'past_due'])

  if (error) {
    logger.error({ err: error }, 'admin/billing/mrr: query failed')
    return NextResponse.json({ error: 'failed to load MRR data' }, { status: 500 })
  }

  const today = new Date()
  const days = eachDayOfInterval({ start: rangeStart, end: today })

  // Build daily MRR series
  const series = days.map(day => {
    const dayStr = format(day, 'yyyy-MM-dd')
    const dayTs = day.getTime()

    const mrr = (subs ?? []).reduce((sum, sub) => {
      const createdAt = new Date(sub.created_at).getTime()
      const cancelledAt = sub.cancelled_at ? new Date(sub.cancelled_at).getTime() : null
      const active = createdAt <= dayTs && (!cancelledAt || cancelledAt > dayTs)
      if (!active) return sum
      const monthly = sub.billing_cycle === 'annual' ? sub.price_cents / 12 : sub.price_cents
      return sum + monthly
    }, 0)

    return { date: dayStr, mrr_cents: Math.round(mrr) }
  })

  // Current MRR
  const currentMrr = series[series.length - 1]?.mrr_cents ?? 0

  // MoM delta — compare current to 30 days ago (or start of series)
  const thirtyDaysAgo = series.find(
    s => s.date === format(subDays(today, 30), 'yyyy-MM-dd'),
  )
  const prevMrr = thirtyDaysAgo?.mrr_cents ?? series[0]?.mrr_cents ?? 0
  const mrrDeltaPct = prevMrr === 0 ? 0 : ((currentMrr - prevMrr) / prevMrr) * 100

  return NextResponse.json({
    mrr_cents: currentMrr,
    mrr_delta_pct: Math.round(mrrDeltaPct * 10) / 10,
    series,
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const QuerySchema = z.object({
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'date must be YYYY-MM-DD'),
})

/**
 * GET /api/admin/billing/day-events?date=2026-03-15
 * Returns billing events (subscription changes, payments) for a single day.
 * Platform admin only.
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const parsed = QuerySchema.safeParse({
    date: req.nextUrl.searchParams.get('date'),
  })
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { date } = parsed.data
  const dayStart = `${date}T00:00:00.000Z`
  const dayEnd   = `${date}T23:59:59.999Z`

  const supabase = createServiceRoleClient()

  // Fetch webhook events for the day (billing events land here from Dodo)
  const { data: events, error } = await supabase
    .from('dodo_webhook_events')
    .select('id, event_type, payload, created_at')
    .gte('created_at', dayStart)
    .lte('created_at', dayEnd)
    .order('created_at', { ascending: true })
    .limit(200)

  if (error) {
    logger.error({ err: error }, 'admin/billing/day-events: query failed')
    return NextResponse.json({ error: 'failed to load events' }, { status: 500 })
  }

  // Map webhook events to a friendly shape for the UI
  interface WebhookPayload {
    studio_name?: string
    amount?: number
    amount_cents?: number
  }
  const mapped = (events ?? []).map(ev => {
    const payload = (ev.payload ?? {}) as WebhookPayload
    return {
      id: ev.id as string,
      type: (ev.event_type as string) ?? 'unknown',
      studio_name: (payload.studio_name as string | undefined) ?? 'Unknown studio',
      amount_cents: (payload.amount_cents as number | undefined) ?? (payload.amount as number | undefined) ?? 0,
      created_at: ev.created_at as string,
    }
  })

  return NextResponse.json({ date, events: mapped })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { format, startOfMonth, addMonths, differenceInCalendarMonths } from 'date-fns'
import type { CohortRow } from '@/components/admin/billing/ChurnCohortGrid'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/billing/churn-cohorts
 * Returns monthly retention cohort grid data.
 * Platform admin only.
 *
 * Algorithm:
 *  1. Fetch all subscriptions (active + cancelled)
 *  2. Group by cohort_month (month of subscription creation)
 *  3. For each cohort × month offset, compute % still active at M+N
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const supabase = createServiceRoleClient()

  const { data: subs, error } = await supabase
    .from('subscriptions')
    .select('id, created_at, cancelled_at, status')
    .order('created_at', { ascending: true })

  if (error) {
    logger.error({ err: error }, 'admin/billing/churn-cohorts: query failed')
    return NextResponse.json({ error: 'failed to load cohort data' }, { status: 500 })
  }

  if (!subs?.length) {
    return NextResponse.json({ cohorts: [] })
  }

  // Group by cohort month
  const cohortMap = new Map<string, { total: number; cancelledAt: (Date | null)[] }>()
  for (const sub of subs) {
    const key = format(startOfMonth(new Date(sub.created_at)), 'yyyy-MM-dd')
    if (!cohortMap.has(key)) cohortMap.set(key, { total: 0, cancelledAt: [] })
    const entry = cohortMap.get(key)!
    entry.total += 1
    entry.cancelledAt.push(sub.cancelled_at ? new Date(sub.cancelled_at) : null)
  }

  const now = new Date()
  const cohorts: CohortRow[] = []

  for (const [cohortMonth, { total, cancelledAt }] of cohortMap.entries()) {
    const cohortDate = new Date(cohortMonth)
    const maxMonthOffset = differenceInCalendarMonths(now, cohortDate)

    const retentions: (number | null)[] = []
    for (let offset = 0; offset <= maxMonthOffset; offset++) {
      const checkDate = addMonths(cohortDate, offset)
      if (checkDate > now) {
        retentions.push(null)
        continue
      }
      const stillActive = cancelledAt.filter(d => d === null || d > checkDate).length
      retentions.push(total > 0 ? Math.round((stillActive / total) * 1000) / 10 : null)
    }

    cohorts.push({ cohort_month: cohortMonth, retentions })
  }

  return NextResponse.json({ cohorts })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import type { LtvBin, LtvStats } from '@/components/admin/billing/LtvHistogram'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/billing/ltv
 * Returns LTV histogram bins + summary stats for all studios.
 * Platform admin only.
 *
 * LTV = total amount paid by each studio's subscription over its lifetime.
 * Bins are $0-$99, $100-$249, $250-$499, $500-$999, $1000-$1999, $2000+
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const supabase = createServiceRoleClient()

  // Aggregate total paid per studio from invoices
  const { data: invoices, error } = await supabase
    .from('invoices')
    .select('studio_id, amount_cents')
    .eq('status', 'paid')

  if (error) {
    logger.error({ err: error }, 'admin/billing/ltv: query failed')
    return NextResponse.json({ error: 'failed to load LTV data' }, { status: 500 })
  }

  if (!invoices?.length) {
    return NextResponse.json({
      bins: [],
      stats: {
        mean_cents: 0,
        median_cents: 0,
        payback_months: 0,
        ltv_cac_ratio: null,
        median_bucket_label: '',
        p90_bucket_label: '',
      },
    })
  }

  // Sum per studio
  const studioLtv = new Map<string, number>()
  for (const inv of invoices) {
    const studioId = inv.studio_id as string
    studioLtv.set(studioId, (studioLtv.get(studioId) ?? 0) + (inv.amount_cents as number))
  }

  const ltvValues = Array.from(studioLtv.values()).sort((a, b) => a - b)
  if (!ltvValues.length) {
    return NextResponse.json({
      bins: [],
      stats: { mean_cents: 0, median_cents: 0, payback_months: 0, ltv_cac_ratio: null, median_bucket_label: '', p90_bucket_label: '' },
    })
  }

  // Define bins (in cents)
  const BIN_DEFS: { label: string; min: number; max: number }[] = [
    { label: '$0–$99',      min: 0,       max: 9_999 },
    { label: '$100–$249',   min: 10_000,  max: 24_999 },
    { label: '$250–$499',   min: 25_000,  max: 49_999 },
    { label: '$500–$999',   min: 50_000,  max: 99_999 },
    { label: '$1,000–$1,999', min: 100_000, max: 199_999 },
    { label: '$2,000+',     min: 200_000, max: Infinity },
  ]

  const bins: LtvBin[] = BIN_DEFS.map(def => ({
    bucket_label: def.label,
    count: ltvValues.filter(v => v >= def.min && v <= def.max).length,
    min: def.min,
    max: def.max === Infinity ? 999_999_999 : def.max,
  }))

  // Stats
  const sum = ltvValues.reduce((a, b) => a + b, 0)
  const mean_cents = Math.round(sum / ltvValues.length)

  const midIdx = Math.floor(ltvValues.length / 2)
  const median_cents = ltvValues.length % 2 === 0
    ? Math.round(((ltvValues[midIdx - 1] ?? 0) + (ltvValues[midIdx] ?? 0)) / 2)
    : (ltvValues[midIdx] ?? 0)

  const p90Idx = Math.floor(ltvValues.length * 0.9)
  const p90Value = ltvValues[p90Idx] ?? 0

  // Payback: median_ltv / avg_mrr_per_studio in months (approximated)
  const avgMrr = mean_cents / 12 // rough: assume 1-year avg lifetime as starting point
  const payback_months = avgMrr > 0 ? Math.round(median_cents / avgMrr) : 0

  // Bucket label for median and p90
  function bucketForValue(v: number): string {
    return BIN_DEFS.find(b => v >= b.min && v <= b.max)?.label ?? BIN_DEFS[BIN_DEFS.length - 1]!.label
  }

  const stats: LtvStats = {
    mean_cents,
    median_cents,
    payback_months,
    ltv_cac_ratio: null, // Would require CAC data (ad spend / new customers) — not tracked yet
    median_bucket_label: bucketForValue(median_cents),
    p90_bucket_label: bucketForValue(p90Value),
  }

  return NextResponse.json({ bins, stats })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServerClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const PostSchema = z.object({
  body: z.string().min(1).max(2000).trim(),
})

/**
 * GET /api/payroll/artist-summaries/:id/comments
 * Returns all comments for an artist summary row.
 * Studio members with payroll access only.
 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params
  const supabase = createServerClient()

  // Verify the summary belongs to this studio
  const { data: summary, error: sumErr } = await supabase
    .from('payroll_artist_summaries')
    .select('id, run:payroll_runs(studio_id)')
    .eq('id', id)
    .single()

  if (sumErr || !summary) {
    return NextResponse.json({ error: 'not found' }, { status: 404 })
  }

  const run = summary.run as { studio_id: string } | null
  if (!run || run.studio_id !== auth.studioId) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const { data: comments, error } = await supabase
    .from('payroll_run_comments')
    .select('id, body, created_at, author_id, author:studio_members(full_name)')
    .eq('artist_summary_id', id)
    .order('created_at', { ascending: true })

  if (error) {
    logger.error({ err: error }, 'payroll/comments: GET failed')
    return NextResponse.json({ error: 'failed to load comments' }, { status: 500 })
  }

  interface RawComment {
    id: string
    body: string
    created_at: string
    author_id: string
    author: { full_name: string } | null
  }

  const shaped = (comments as unknown as RawComment[]).map(c => ({
    id: c.id,
    body: c.body,
    created_at: c.created_at,
    author_id: c.author_id,
    author_name: c.author?.full_name ?? 'Team member',
  }))

  return NextResponse.json({ data: shaped })
}

/**
 * POST /api/payroll/artist-summaries/:id/comments
 * Adds a comment to an artist summary.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params

  const body = await req.json().catch(() => null)
  const parsed = PostSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const supabase = createServerClient()

  // Verify the summary belongs to this studio
  const { data: summary, error: sumErr } = await supabase
    .from('payroll_artist_summaries')
    .select('id, run:payroll_runs(studio_id)')
    .eq('id', id)
    .single()

  if (sumErr || !summary) {
    return NextResponse.json({ error: 'not found' }, { status: 404 })
  }

  const run = summary.run as { studio_id: string } | null
  if (!run || run.studio_id !== auth.studioId) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const { data: comment, error } = await supabase
    .from('payroll_run_comments')
    .insert({
      artist_summary_id: id,
      author_id: auth.member.id,
      body: parsed.data.body,
    })
    .select('id, body, created_at, author_id')
    .single()

  if (error) {
    logger.error({ err: error }, 'payroll/comments: POST failed')
    return NextResponse.json({ error: 'failed to save comment' }, { status: 500 })
  }

  return NextResponse.json({
    data: {
      id: comment.id,
      body: comment.body,
      created_at: comment.created_at,
      author_id: comment.author_id,
      author_name: auth.member.full_name ?? 'Team member',
    },
  }, { status: 201 })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServerClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
