import { logger } from '@/lib/logger'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const QuerySchema = z.object({
  preset: z.enum(['accountant', 'commission_detail', '1099_export']),
  from: z.string().optional(),
  to: z.string().optional(),
})

/**
 * GET /api/payroll/export?preset=accountant&from=2026-01-01&to=2026-03-31
 * Generates and streams a CSV of payroll data.
 * Owner / manager only.
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (auth.member.role !== 'owner' && auth.member.role !== 'manager') {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const params = Object.fromEntries(req.nextUrl.searchParams.entries())
  const parsed = QuerySchema.safeParse(params)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { preset, from, to } = parsed.data
  const supabase = createServerClient()

  let csvRows: string[] = []

  if (preset === 'accountant') {
    let query = supabase
      .from('payroll_artist_summaries')
      .select(`
        artist_name_snapshot,
        gross_total_cents,
        adjustments_total_cents,
        net_total_cents,
        run:payroll_runs(period_start, period_end, studio_id)
      `)
      .eq('run.studio_id', auth.studioId)

    if (from) query = query.gte('run.period_start', from)
    if (to)   query = query.lte('run.period_end', to)

    const { data, error } = await query

    if (error) {
      logger.error({ err: error }, 'payroll/export: accountant query failed')
      return NextResponse.json({ error: 'export failed' }, { status: 500 })
    }

    interface AccountantRow {
      artist_name_snapshot: string
      gross_total_cents: number
      adjustments_total_cents: number
      net_total_cents: number
      run: { period_start: string; period_end: string } | null
    }

    csvRows = [
      'Artist,Period Start,Period End,Gross,Adjustments,Net',
      ...(data as unknown as AccountantRow[]).map(r =>
        [
          `"${r.artist_name_snapshot}"`,
          r.run?.period_start ?? '',
          r.run?.period_end ?? '',
          (r.gross_total_cents / 100).toFixed(2),
          (r.adjustments_total_cents / 100).toFixed(2),
          (r.net_total_cents / 100).toFixed(2),
        ].join(',')
      ),
    ]
  } else if (preset === 'commission_detail') {
    let query = supabase
      .from('commission_records')
      .select(`
        id,
        booking_id,
        amount_cents,
        rate_pct,
        status,
        created_at,
        artist:studio_members!artist_id(full_name)
      `)
      .eq('studio_id', auth.studioId)
      .eq('status', 'approved')

    if (from) query = query.gte('created_at', from)
    if (to)   query = query.lte('created_at', to)

    const { data, error } = await query

    if (error) {
      logger.error({ err: error }, 'payroll/export: commission detail query failed')
      return NextResponse.json({ error: 'export failed' }, { status: 500 })
    }

    interface CommissionRow {
      id: string
      booking_id: string
      amount_cents: number
      rate_pct: number
      status: string
      created_at: string
      artist: { full_name: string } | null
    }

    csvRows = [
      'ID,Artist,Booking ID,Amount,Rate %,Status,Date',
      ...(data as unknown as CommissionRow[]).map(r =>
        [
          r.id,
          `"${r.artist?.full_name ?? ''}"`,
          r.booking_id,
          (r.amount_cents / 100).toFixed(2),
          r.rate_pct,
          r.status,
          r.created_at.slice(0, 10),
        ].join(',')
      ),
    ]
  } else {
    // 1099 export — contractor earnings summary
    const { data, error } = await supabase
      .from('artist_tax_info')
      .select(`
        legal_name,
        tax_id_type,
        address_line1,
        city,
        state,
        zip,
        artist:studio_members!artist_id(full_name)
      `)
      .eq('studio_id', auth.studioId)

    if (error) {
      logger.error({ err: error }, 'payroll/export: 1099 query failed')
      return NextResponse.json({ error: 'export failed' }, { status: 500 })
    }

    interface TaxRow {
      legal_name: string
      tax_id_type: string
      address_line1: string
      city: string
      state: string
      zip: string
      artist: { full_name: string } | null
    }

    csvRows = [
      'Artist,Legal Name,Tax ID Type,Address,City,State,ZIP',
      ...(data as unknown as TaxRow[]).map(r =>
        [
          `"${r.artist?.full_name ?? ''}"`,
          `"${r.legal_name}"`,
          r.tax_id_type,
          `"${r.address_line1}"`,
          r.city,
          r.state,
          r.zip,
        ].join(',')
      ),
    ]
  }

  const csv = csvRows.join('\n')
  const filename = `payroll-${preset}-${new Date().toISOString().slice(0, 10)}.csv`

  return new NextResponse(csv, {
    status: 200,
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="${filename}"`,
    },
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServerClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  preset: z.enum(['accountant', 'commission_detail', '1099_export']),
  from: z.string().optional(),
  to: z.string().optional(),
})

/**
 * POST /api/payroll/export/estimate
 * Returns row count estimate for the given export parameters.
 * Used by CsvExportModal to decide between direct download vs BullMQ queue.
 */
export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (auth.member.role !== 'owner' && auth.member.role !== 'manager') {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const body = await req.json().catch(() => null)
  const parsed = BodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { preset, from, to } = parsed.data
  const supabase = createServerClient()

  let count = 0

  if (preset === 'commission_detail') {
    let query = supabase
      .from('commission_records')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', auth.studioId)
      .eq('status', 'approved')

    if (from) query = query.gte('created_at', from)
    if (to)   query = query.lte('created_at', to)

    const { count: c } = await query
    count = c ?? 0
  } else if (preset === 'accountant') {
    let query = supabase
      .from('payroll_artist_summaries')
      .select('id', { count: 'exact', head: true })

    if (from) query = query.gte('created_at', from)
    if (to)   query = query.lte('created_at', to)

    const { count: c } = await query
    count = c ?? 0
  } else {
    const { count: c } = await supabase
      .from('artist_tax_info')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', auth.studioId)
    count = c ?? 0
  }

  return NextResponse.json({ count })
}

